import {steps,photos,sources,checked} from './data.js';
import {read,write,normalize} from './state.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const emphasis=[
{big:'무료 셔틀 표지를 찾으세요',sub:'가는 방향은 T1 · 공항역입니다',icon:'🚌'},
{big:'하차 후, 2층 철도역으로',sub:'에어로플라자 1층 → 2층 → 연결 통로',icon:'↗'},
{big:'NANKAI · 난바행 탑승',sub:'1·2번 중 당일 전광판 확인 · 종점에서 하차',icon:'🚆'},
{big:'북쪽 개찰구 → 지하 1층',sub:'3층 → 1층 → B1 · 빨간 M 표지를 따라가세요',icon:'↘'},
{big:'2번 승강장 · 우메다 방면',sub:'반대쪽 1번은 타지 마세요 · 한 정거장만!',icon:'②'},
{big:'1번 출구 → 케즈빌딩 10층',sub:'주소와 건물 이름을 확인한 뒤 올라가세요',icon:'🏁'}];
function highlight(a){return esc(a).replace(/(無料連絡バス|Free Shuttle Bus|T1・空港駅|空港駅・第1ターミナル・エアロプラザ|鉄道|Railway|2층|1층|3F北改札口|North Gate|南北改札|Minami-kita Gate|南海|NANKAI|なんば|Namba|3·4번|1·2번|2番線|Platform 2|梅田・新大阪・箕面萱野方面|for Umeda, Shin-Osaka, Minoh-kayano|한 정거장|心斎橋|Shinsaibashi M19|8호차|9호차|北改札|1番出口|Exit 1|ケーズビル|K’s Building|10층)/g,'<mark>$1</mark>');}
function decision(s){const e=emphasis[s.id-1];return `<div class="decision"><span class="decision-icon" aria-hidden="true">${e.icon}</span><div><small>지금 해야 할 일</small><strong>${e.big}</strong><p>${e.sub}</p></div></div>`;}

let storage;try{storage=localStorage;}catch{}let state=read(storage),tab='guide';
function source(id){return sources.find(s=>s.id===id);}
function link(s){return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`;}
function photo(key){const p=photos[key];return `<figure class="photo"><button data-photo="${key}" aria-label="${esc(p.alt)} · 크게 보기"><img src="${esc(p.src)}" alt="${esc(p.alt)}" loading="lazy" referrerpolicy="no-referrer"><span class="zoom">확대 ↗</span></button><p>${esc(p.note)}</p><figcaption>${esc(p.credit)}<br>${esc(p.date)} · ${link(source(p.source))}</figcaption></figure>`;}
function save(){if(!write(storage,state))$('#status').textContent='이 브라우저에서는 진행 상태를 저장할 수 없어요. 현재 화면은 계속 사용할 수 있습니다.';}
function jump(n){state.current=n;tab='guide';location.hash=`step-${n}`;save();render();$('#view').focus({preventScroll:true});$('#view').scrollIntoView({behavior:'smooth',block:'start'});}
function render(){const s=steps[state.current-1];$('#progress').value=state.done.length;$('#progressText').textContent=`${state.done.length} / 6 완료`;$('#stepNav').innerHTML=steps.map(x=>`<button data-step="${x.id}" class="${state.done.includes(x.id)?'done':''}" ${x.id===state.current?'aria-current="step"':''} aria-label="${x.id}단계 ${esc(x.title)}${state.done.includes(x.id)?' 완료':''}">${state.done.includes(x.id)?'✓':x.id}<small>${['출구','셔틀','난카이','환승','지하철','도착'][x.id-1]}</small></button>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===tab));$('#bottom').innerHTML=tab==='guide'?`<button class="secondary" id="previous" ${s.id===1?'disabled':''}>← 이전</button><button class="primary" id="next">${s.id===6?'병원 도착 · 완료 ✓':'여기까지 왔어요 · 다음 →'}</button>`:'';$('#bottom').hidden=tab!=='guide';
if(tab==='guide')$('#view').innerHTML=`${state.done.length===6?'<div class="success"><strong>도착하셨네요. 수고하셨어요! ✓</strong><br>접수에서 예약 화면을 보여주세요.</div>':''}<article class="card"><div class="tag">STEP 0${s.id} / 06 &nbsp; ${esc(s.tag)}</div><h2>${s.icon} ${esc(s.title)}</h2>${decision(s)}<div class="place-pair"><small>지금</small><strong>${esc(s.from)}</strong><small>다음</small><strong>→ ${esc(s.to)}</strong></div><p class="time">◷ ${esc(s.time)}</p><ol class="actions">${s.actions.map(a=>`<li>${highlight(a)}</li>`).join('')}</ol><div class="sign-label">이 글자가 보이면 맞게 가고 있어요</div><div class="sign ${s.id===5?'metro':''}">${esc(s.sign)}</div><div class="warning"><span class="warning-label">⚠ 여기서 헷갈리지 마세요</span>${esc(s.warning)}</div>${s.photo?photo(s.photo):''}${(s.gallery||[]).map(photo).join('')}<p class="note">${esc(s.extra)}</p><a class="map-link" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(s.map)}&travelmode=walking" target="_blank" rel="noopener noreferrer">${s.id===6?'병원까지 도보 길안내':'이 단계 목적지 지도 보기'} ↗</a><p class="save-note">지도에는 현재 위치 권한·인터넷이 필요할 수 있어요. 역 안에서는 위 표지판 안내를 우선하세요.</p><label class="complete"><input id="complete" type="checkbox" ${state.done.includes(s.id)?'checked':''}>이 단계 이동 완료</label><div class="refs">${s.refs.map(id=>link(source(id))).join('')}</div></article><div class="summary"><h3>이것만 기억하세요</h3><p>① 무료 셔틀 → <b>에어로플라자</b></p><p>② <b>난카이 난바행</b> → 3층 북쪽 개찰구</p><p>③ 빨간 M · <b>2번 승강장, 우메다 방면</b></p><p>④ <b>한 정거장</b> → 신사이바시 · 1번 출구</p></div>`;
if(tab==='route')$('#view').innerHTML=`<h2>한눈에 보는 여섯 단계</h2><img class="route-diagram" src="route-map.svg" alt="무료 셔틀, 난카이 난바행, 미도스지선 우메다 방면을 거쳐 신사이바시로 가는 여섯 단계"><p class="note">완료 표시는 이 브라우저에만 저장돼요. 단계를 눌러 안내를 다시 볼 수 있습니다.</p>${steps.map(x=>`<button class="overview" data-step="${x.id}"><span class="num">${state.done.includes(x.id)?'✓':x.id}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.from)} → ${esc(x.to)}</small><small>${esc(x.time)}</small></span><span>↗</span></button>`).join('')}<div class="card"><h3>예상 시간은 어떻게 읽나요?</h3><p>전체 85~120분은 가족 3명이 짐을 가지고 이동할 때 여유를 둔 계획 범위입니다. 셔틀·열차 승차시간과 도보·발권·대기 예상치를 합쳐 반올림했습니다. 각 구간의 최대 대기가 모두 겹치거나 운행이 지연되면 120분을 넘을 수 있어요.</p><p>출발 기준은 <b>수하물 수령과 세관까지 끝난 시점</b>입니다. 입국심사·수하물 대기는 별도입니다.</p><p>특정 날짜의 열차 시각표와 연결 열차를 확정한 일정이 아닙니다. 공식 안내와 당일 전광판을 확인하세요.</p></div>`;
if(tab==='sources')$('#view').innerHTML=`<div class="card"><div class="tag">원본 사진 · 확인 근거</div><h2>사진과 안내를 구분했어요</h2><p>사진을 AI로 다시 그리거나 표지판 글자를 바꾸지 않았습니다. 최신 취재 사진과 촬영일이 알려지지 않은 안내 사진을 구별합니다.</p><div class="warning">국제선 도착 로비의 출입문 근접 사진과 빨간 M 표지판의 최신 근접 사진은 확보하지 못했습니다. 해당 부분은 공식 안내·표지판 문구로 안내합니다.</div>${Object.keys(photos).map(photo).join('')}<p class="note">블로그 사진은 원문 서버에서 불러옵니다. 저장소에 복제하지 않으며, 연결 차단·오프라인 시 표시되지 않을 수 있습니다. 원문 링크로 확인하세요. 오사카시 사진만 CC BY 4.0 조건에 따라 동봉합니다.</p><h3>공식 안내와 보조 자료</h3>${sources.map(s=>`<section class="source-card">${link(s)}<p>${esc(s.fact)}</p><small>확인일 ${checked}</small></section>`).join('')}</div>`;
if(tab==='help')$('#view').innerHTML=`<div class="card"><h2>잠깐, 도움이 필요할 때</h2><p>현재 단계의 문장을 직원에게 보여주세요.</p><div class="help-phrase"><small>현재 단계 목적지를 찾고 있어요</small><p>${esc(phrase())}</p><button class="small" id="copyPhrase">일본어 복사</button></div><h3>예약 시간을 적어두세요</h3><label class="date" for="appointment">방문 예정 일시 (일본 현지시각)</label><input id="appointment" type="datetime-local" value="${esc(state.appointment)}"><p class="save-note">선택 사항 · 이 브라우저에만 저장 · 공유 링크에 포함되지 않습니다.</p><h3>통신·짐·이동 팁</h3><p>인터넷 연결 상태에서 한 번 열면 안내 문구와 동봉 사진을 오프라인에서도 사용할 수 있습니다. 외부 사진·지도·공식 사이트에는 인터넷이 필요해요.</p><p>앱의 단계 표시는 사용자가 누른 진행 상태입니다. 실시간 위치를 추적하거나 열차 지연을 자동 반영하지 않습니다.</p><p>난카이와 지하철은 운임 체계가 달라요. 교통카드로 각각 개찰하고, 라피트는 별도 지정석 특급권을 준비하세요.</p><a class="map-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('大阪市中央区南船場3-6-18 ケーズビル')}" target="_blank" rel="noopener noreferrer">병원 주소 지도 보기 ↗</a><button class="small" id="copyAddress">병원 주소 복사</button><h3>진행 기록 관리</h3><button class="secondary" id="reset">진행 기록과 입력한 시간 지우기</button></div>`;
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>jump(Number(b.dataset.step)));document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openPhoto(b.dataset.photo));document.querySelectorAll('.photo img').forEach(img=>img.onerror=()=>{const b=img.parentElement;b.disabled=true;b.innerHTML='<span class="image-error">사진을 불러오지 못했어요.<br>아래 원문 링크에서 확인하세요.</span>';});
if($('#previous'))$('#previous').onclick=()=>jump(Math.max(1,s.id-1));if($('#next'))$('#next').onclick=()=>{if(!state.done.includes(s.id))state.done.push(s.id);save();if(s.id<6)jump(s.id+1);else{render();$('#status').textContent='모든 단계가 완료되었습니다.';}};if($('#complete'))$('#complete').onchange=e=>{state.done=e.target.checked?[...new Set([...state.done,s.id])]:state.done.filter(n=>n!==s.id);save();render();};if($('#appointment'))$('#appointment').onchange=e=>{state.appointment=e.target.value;state=normalize(state);save();};if($('#copyPhrase'))$('#copyPhrase').onclick=()=>copy(phrase());if($('#copyAddress'))$('#copyAddress').onclick=()=>copy('大阪市中央区南船場3-6-18 ケーズビル10F');if($('#reset'))$('#reset').onclick=()=>{if(confirm('완료 표시와 입력한 방문 시간을 지울까요?')){state=normalize();save();tab='guide';location.hash='step-1';render();}};}
function phrase(){return ['空港駅・第1ターミナル行きの無料連絡バス乗り場はどこですか？','関西空港駅の南海電車の改札はどこですか？','なんば行きの南海電車はどこから乗れますか？','地下鉄御堂筋線の南北改札はどこですか？','御堂筋線の梅田・新大阪方面、2番線はどこですか？','南船場3-6-18、ケーズビル10階に行きたいです。'][state.current-1];}
function openPhoto(key){const p=photos[key];$('#largePhoto').src=p.src;$('#largePhoto').alt=p.alt;$('#photoCaption').textContent=`${p.credit} / ${p.date} — ${p.note}`;$('#photoSource').href=source(p.source).url;$('#photoDialog').showModal();}
async function copy(text){try{await navigator.clipboard.writeText(text);$('#status').textContent='복사했어요.';}catch{$('#status').textContent='복사를 지원하지 않는 환경입니다. 화면의 문구를 직접 보여주세요.';}}
$('#closePhoto').onclick=()=>$('#photoDialog').close();$('#photoDialog').onclick=e=>{if(e.target===$('#photoDialog'))$('#photoDialog').close();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});$('#share').onclick=async()=>{const url=new URL(location.href);url.hash='';try{if(navigator.share)await navigator.share({title:'오사카 길동무',text:'간사이공항에서 신사이바시까지 한 단계씩',url:url.href});else await copy(url.href);}catch(e){if(e.name!=='AbortError')await copy(url.href);}};window.addEventListener('hashchange',()=>{const n=Number(location.hash.replace('#step-',''));if(n>=1&&n<=6&&Number.isInteger(n)){state.current=n;tab='guide';save();render();}});if(/^#step-[1-6]$/.test(location.hash))state.current=Number(location.hash.slice(-1));render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
